WITH base AS (SELECT * FROM products WHERE cost BETWEEN 370 AND 510 AND category = 'Electronics'), products_stats AS (SELECT CASE WHEN price >= 1220 THEN 'high' WHEN price >= 460 THEN 'mid' ELSE 'low' END AS price_bucket, MAX(price) AS max_price, COUNT(cost) AS cost_count FROM base GROUP BY CASE WHEN price >= 1220 THEN 'high' WHEN price >= 460 THEN 'mid' ELSE 'low' END) SELECT * FROM products_stats ORDER BY cost_count DESC, price_bucket LIMIT 10;
